      "layout": "standardStudy",
      "translation": "richiamarsi a • appellarsi a",
      "explanation": [
        "Idea principale: sich berufen auf è un verbo riflessivo che significa richiamarsi a qualcosa come base di un argomento: a una legge, a un contratto, a una fonte o a una persona. Dopo auf segue l'accusativo: sich auf etwas berufen.",
        "Forme: beruft sich, berief sich, hat sich berufen. Il prefisso be- non è separabile.",
        "Da solo, berufen (senza sich) significa nominare a una carica: Er wurde zum Professor berufen. È un significato diverso dal richiamarsi."
      ],
      "examples": [
        {
          "de": "Er beruft sich auf sein Recht.",
          "lv": "Si appella al suo diritto."
        },
        {
          "de": "Der Politiker beruft sich auf eine Studie.",
          "lv": "Il politico si richiama a uno studio."
        },
        {
          "de": "Sie berief sich auf den Vertrag.",
          "lv": "Si richiamò al contratto."
        },
        {
          "de": "Dabei kann ich mich auf niemanden berufen.",
          "lv": "Su questo non posso richiamarmi a nessuno."
        }
      ],
      "comparison": [
        {
          "word": "verweisen auf",
          "meaning": "rimandare a",
          "example": "Er verweist auf den Artikel. – Rimanda all'articolo."
        },
        {
          "word": "sich stützen auf",
          "meaning": "basarsi su",
          "example": "Das Urteil stützt sich auf Beweise. – La sentenza si basa su prove."
        },
        {
          "word": "zitieren",
          "meaning": "citare",
          "example": "Sie zitiert den Autor. – Cita l'autore."
        }
      ],
      "tip": [
        "Si usa auf + accusativo: auf das Gesetz, auf einen Zeugen.",
        "Nel linguaggio giuridico e dei tribunali sich berufen auf è una formula di base."
      ],
      "important": [
        "Sich berufen auf non è la stessa cosa di berufen: senza sich significa nominare (a una carica).",
        "Il Perfekt è hat sich berufen (senza ge-)."
      ],
