      "translation": "rivelarsi • risultare",
      "explanation": [
        "Idea principale: sich herausstellen significa rivelarsi, risultare — diventa chiaro che cosa sia davvero una persona o una cosa. Con als + nominativo: Er stellte sich als Betrüger heraus. Formula tipica: Es stellte sich heraus, dass …",
        "Particella separabile heraus-: stellt sich heraus, stellte sich heraus, hat sich herausgestellt. Il soggetto è di solito una cosa o un'informazione, ma può essere anche una persona."
      ],
      "examples": [
        {
          "de": "Es stellte sich heraus, dass er recht hatte.",
          "lv": "Si è scoperto che aveva ragione."
        },
        {
          "de": "Der Verdacht stellte sich als falsch heraus.",
          "lv": "Il sospetto si è rivelato infondato."
        },
        {
          "de": "Das Projekt hat sich als großer Erfolg herausgestellt.",
          "lv": "Il progetto si è rivelato un grande successo."
        },
        {
          "de": "Wer der Täter ist, wird sich bald herausstellen.",
          "lv": "Presto si scoprirà chi è il colpevole."
        }
      ],
      "comparison": [
        {
          "word": "sich erweisen",
          "meaning": "rivelarsi, dimostrarsi",
          "example": "Die Methode erwies sich als nützlich. – Il metodo si è rivelato utile."
        },
        {
          "word": "sich zeigen",
          "meaning": "mostrarsi, apparire",
          "example": "Es zeigte sich, dass er müde war. – Si è visto che era stanco."
        },
        {
          "word": "herausfinden",
          "meaning": "scoprire",
          "example": "Ich finde das heraus. – Lo scoprirò."
        }
      ],
      "tip": [
        "A inizio frase è comodo usare Es stellte sich heraus, dass … — si è scoperto che …",
        "Con als si indica il risultato: sich als falsch herausstellen."
      ],
      "important": [
        "La particella heraus- si separa: Es stellt sich heraus, non es herausstellt sich.",
        "Non confonderlo con herausstellen senza sich (mettere in evidenza, tirare fuori): etwas herausstellen."
      ],
