      "translation": "unirsi • fondersi",
      "explanation": [
        "Idea principale: sich vereinigen significa unirsi, riunirsi insieme — detto di stati, partiti, aziende, forze. Con mit + dativo si indica il partner: sich mit einer Gruppe vereinigen. Il risultato si indica con zu + dativo: sich zu einer Union vereinigen.",
        "Forme: vereinigt sich, vereinigte sich, hat sich vereinigt. Senza sich, vereinigen è transitivo: Länder vereinigen — unire dei paesi. Esempio in un nome: die Vereinigten Staaten (gli Stati Uniti)."
      ],
      "examples": [
        {
          "de": "Die beiden Firmen vereinigten sich zu einem Konzern.",
          "lv": "Le due aziende si fusero in un unico gruppo."
        },
        {
          "de": "Die Partei vereinigte sich mit einer kleineren Gruppe.",
          "lv": "Il partito si unì a un gruppo più piccolo."
        },
        {
          "de": "Die Länder haben sich zu einer Union vereinigt.",
          "lv": "I paesi si sono uniti in un'unione."
        },
        {
          "de": "Alle Kräfte vereinigten sich gegen den Gegner.",
          "lv": "Tutte le forze si unirono contro l'avversario."
        }
      ],
      "comparison": [
        {
          "word": "vereinen",
          "meaning": "unire",
          "example": "Das Fest vereint alle Generationen. – La festa unisce tutte le generazioni."
        },
        {
          "word": "sich zusammenschließen",
          "meaning": "unirsi, associarsi",
          "example": "Die Firmen schließen sich zusammen. – Le aziende si uniscono."
        },
        {
          "word": "fusionieren",
          "meaning": "fondersi",
          "example": "Zwei Banken fusionieren. – Due banche si fondono."
        }
      ],
      "tip": [
        "Combinazione frequente: sich zu etwas vereinigen (unirsi in qualcosa).",
        "Nella vita quotidiana spesso è più semplice: sich zusammenschließen."
      ],
      "important": [
        "Il vicino vereinen (unire) di solito si riferisce a persone e sentimenti, mentre vereinigen più spesso a organizzazioni e stati.",
        "Dopo mit segue il dativo: mit der Partei, mit dem Nachbarn."
      ],
