        "Verbo regolare: er fordert, forderte, hat gefordert. Ciò che si esige va all'accusativo, da chi — von + dativo: etwas von jemandem fordern. Può seguire anche una frase con dass. In senso figurato fordern può significare causare vittime: Der Unfall forderte zwei Todesopfer.",
